'use client'

import * as React from 'react'
import Tabs from '@radui/ui/Tabs'

import './sliding-tabs.css'

export type SlidingTab = {
    value: string
    label: React.ReactNode
    content: React.ReactNode
}

export type SlidingTabsProps = {
    tabs: SlidingTab[]
    defaultValue?: string
    value?: string
    onValueChange?: (value: string) => void
    className?: string
}

// Rad UI Tabs owns the behaviour: roles, arrow-key navigation, focus and
// selection. This component only adds the sliding indicator and a content fade.
const SlidingTabs = ({ tabs, defaultValue, value, onValueChange, className }: SlidingTabsProps) => {
    const [internal, setInternal] = React.useState(defaultValue ?? tabs[0]?.value)
    const current = value ?? internal
    const listRef = React.useRef<HTMLDivElement | null>(null)
    const triggerRefs = React.useRef(new Map<string, HTMLElement>())
    const [indicator, setIndicator] = React.useState<{ left: number, width: number } | null>(null)

    const measure = React.useCallback(() => {
        const trigger = current ? triggerRefs.current.get(current) : undefined
        if (!trigger) return
        setIndicator({ left: trigger.offsetLeft, width: trigger.offsetWidth })
    }, [current])

    React.useLayoutEffect(() => { measure() }, [measure])

    React.useEffect(() => {
        const list = listRef.current
        if (!list || typeof ResizeObserver === 'undefined') return
        const observer = new ResizeObserver(measure)
        observer.observe(list)
        return () => observer.disconnect()
    }, [measure])

    const handleChange = (next: string) => {
        if (value === undefined) setInternal(next)
        onValueChange?.(next)
    }

    return <Tabs.Root
        // Own class namespace: Rad UI theme styles stay off, this file's CSS is the only styling.
        customRootClass="rad-fx-sliding-tabs"
        className={className}
        value={current}
        onValueChange={handleChange}
    >
        <Tabs.List ref={listRef} className="rad-fx-sliding-tabs-list">
            {indicator ? <span
                className="rad-fx-sliding-tabs-indicator"
                aria-hidden="true"
                style={{ transform: `translateX(${indicator.left}px)`, width: indicator.width }}
            /> : null}
            {tabs.map((tab) => (
                <Tabs.Trigger
                    key={tab.value}
                    value={tab.value}
                    className="rad-fx-sliding-tabs-trigger"
                    ref={(node: HTMLElement | null) => {
                        if (node) triggerRefs.current.set(tab.value, node)
                        else triggerRefs.current.delete(tab.value)
                    }}
                >
                    {tab.label}
                </Tabs.Trigger>
            ))}
        </Tabs.List>
        {tabs.map((tab) => (
            <Tabs.Content key={tab.value} value={tab.value} className="rad-fx-sliding-tabs-content">
                {tab.content}
            </Tabs.Content>
        ))}
    </Tabs.Root>
}

export default SlidingTabs

.rad-fx-sliding-tabs-list {
    position: relative;
    display: inline-flex;
    gap: 2px;
    padding: 4px;
    border-radius: 10px;
    background: rgb(127, 127, 127, 0.12);
}

.rad-fx-sliding-tabs-indicator {
    position: absolute;
    top: 4px;
    bottom: 4px;
    left: 0;
    border-radius: 7px;
    background: rgb(127, 127, 127, 0.28);
    transition: transform 320ms cubic-bezier(0.2, 0.7, 0.2, 1), width 320ms cubic-bezier(0.2, 0.7, 0.2, 1);
}

.rad-fx-sliding-tabs-trigger {
    position: relative;
    z-index: 1;
    padding: 6px 14px;
    border: 0;
    border-radius: 7px;
    background: transparent;
    color: inherit;
    font: inherit;
    font-size: 0.9rem;
    cursor: pointer;
}

/* Active state is carried by the indicator and weight, never by fading the text,
   so every label keeps full contrast. */
.rad-fx-sliding-tabs-trigger[data-state='active'] { font-weight: 600; }

.rad-fx-sliding-tabs-trigger:focus-visible {
    outline: 2px solid currentcolor;
    outline-offset: 2px;
}

.rad-fx-sliding-tabs-content[data-state='active'] {
    animation: rad-fx-sliding-tabs-in 300ms ease both;
}

@keyframes rad-fx-sliding-tabs-in {
    from { opacity: 0; transform: translateY(4px); }
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-sliding-tabs-indicator { transition: none; }
    .rad-fx-sliding-tabs-content[data-state='active'] { animation: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-sliding-tabs-indicator { transition: none; }
[data-rad-fx-motion='reduce'] .rad-fx-sliding-tabs-content[data-state='active'] { animation: none; }
